import{_ as t,o as a,c as s,j as e}from"./chunks/framework.DJo0M80U.js";const S=JSON.parse('{"title":"CASE语句","description":"","frontmatter":{"title":"CASE语句","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/CASE语句.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/CASE语句.md"}'),l={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/CASE语句.md"};function o(n,E,r,N,p,c){return a(),s("div",null,[...E[0]||(E[0]=[e("div",null,[e("p",null,"在 SQL 中，CASE 表达式是一种条件表达式，可以基于条件来返回不同的值。它的基本格式如下： CASE WHEN condition1 THEN result1 WHEN condition2 THEN result2 ... ELSE resultN END"),e("p",null,"其中： WHEN condition1：第一个条件。 THEN result1：当 condition1 为真时返回的结果。 这样的 WHEN ... THEN ... 可以有多个。 ELSE resultN：所有给定的条件都不为真时返回的结果。 END：结束 CASE 表达式。"),e("p",null,"你提供的示例： CASE WHEN eval.ID IS NOT NULL THEN '达标' ELSE '未达标' END AS type"),e("p",null,"在这个示例中： 如果 eval.ID 不为 NULL，则返回 '达标'。 否则，返回 '未达标'。 这意味着，基于 eval.ID 是否为 NULL，该表达式会为每一行返回 '达标' 或 '未达标'。"),e("p",null,"更多的示例： 基于数值范围返回字符串： SELECT CASE WHEN score >= 90 THEN '优秀' WHEN score >= 70 THEN '良好' WHEN score >= 50 THEN '合格' ELSE '不合格' END AS performance FROM students_scores;"),e("p",null,"在上面的示例中，我们基于 score 列的值为每位学生返回一个表示表现的字符串。"),e("p",null,"使用CASE在计算中： SELECT CASE WHEN age < 18 THEN price * 0.5 ELSE price END AS discounted_price FROM products;"),e("p",null,"在这个示例中，如果 age 小于 18，我们返回商品的半价，否则返回原价。"),e("p",null,"CASE 表达式非常强大，并可以用在几乎任何地方：在 SELECT、WHERE、ORDER BY 和其他子句中。")],-1)])])}const d=t(l,[["render",o]]);export{S as __pageData,d as default};
